def launch(task):
    if not task.get("id") or not task.get("owner"):
        raise ValueError("id and owner required")
    if task.get("project") != "river" or task.get("kind") != "health":
        raise ValueError("unsupported project policy")
    task["priority"] = "high"
    return {"delivered": task["id"], "owner": task["owner"]}

